  function icon(name) {
    const item = ICONS[name];
    if (!item) return "";
    return '<svg class="ci-svg" viewBox="' + item[0] + '" fill="currentColor" aria-hidden="true" focusable="false">' + item[1] + "</svg>";
  }
  function hydrate(root) {
    (root || document).querySelectorAll("[data-icon]").forEach(function (el) {
      if (!el.firstChild) el.innerHTML = icon(el.getAttribute("data-icon"));
    });
  }
  window.PopIcons = { icon: icon, hydrate: hydrate };
  hydrate(document);
